"""Incremental, closed synthetic economy with commercial-bank settlement.

Policy is a per-step action, never a rewritten simulation configuration. All
monetary state lives exclusively in the bank ledger. Production converts paid
labor into indivisible goods; household purchases consume goods immediately.
Reported profit is revenue less this step's production cash outlay (not accrual
profit or inventory valuation). Bankruptcy is an explicit policy decision; it
freezes remaining inventory and writes off principal without seizing deposits.
No interest, labor supply limit, price discovery, collateral recovery, central
bank reaction, calibrated behavior, or causal validation is asserted.

Work is conservatively preflighted across the entire retained policy history:
at most 10000 reserved transactions and 1000000 transaction × ledger-balance
cells. Every purchase entry reserves a slot, even if zero or later rationed;
production reserves origination and wage-payment slots. These bounds constrain
the household/firm cross-product and retained journals, not just actor count.
"""
from copy import deepcopy
from .banking import _money, _units, simulate_banking


def _object(value, allowed, name):
    if not isinstance(value, dict) or set(value) - set(allowed):
        raise ValueError(f'Unknown or invalid {name} fields')


def _count(value, name):
    if isinstance(value, bool) or not isinstance(value, int) or not 0 <= value <= 1000000:
        raise ValueError(f'{name} must be an integer between zero and 1000000')
    return value


def _work_budget(state, policies=()):
    """Bound ledger-copy work and retained journals before any transactions.

    Recompute from policies rather than trusting a mutable accumulated counter.
    Each firm's possible loan is included in the ledger size even before it is
    originated, so future loan creation cannot invalidate the estimate.
    """
    firms = {firm['id'] for firm in state['firms']}
    households = {household['id'] for household in state['households']}
    balance_cells = 3 * len(state['banks']) + 2 * len(firms) + len(households)
    transactions = postings = 0

    def reserve(policy, journal=()):
        nonlocal transactions, postings
        _object(policy, ('firms', 'households'), 'policy')
        slots = 0
        for name, owners in (('firms', firms), ('households', households)):
            mapping = policy.get(name, {})
            if not isinstance(mapping, dict) or set(mapping) - owners:
                raise ValueError('Policy references unknown actor')
        for action in policy.get('firms', {}).values():
            _object(action, ('production', 'price', 'credit_limit', 'repay', 'bankrupt'), 'firm action')
            bankrupt = action.get('bankrupt', False)
            if not isinstance(bankrupt, bool):
                raise ValueError('bankrupt must be boolean')
            slots += 2 * (_count(action.get('production', 0), 'production') > 0)
            slots += (_money(action.get('repay', 0), 'repay') > 0) + bankrupt
        for action in policy.get('households', {}).values():
            _object(action, ('purchases',), 'household action')
            purchases = action.get('purchases', {})
            if not isinstance(purchases, dict) or set(purchases) - firms:
                raise ValueError('Unknown purchase firm')
            # Count all entries, including no-op or rationed requests: they still
            # consume per-step processing and remain in the policy audit.
            slots += len(purchases)
        if not isinstance(journal, (list, tuple)):
            raise ValueError('History journal must be a list')
        actual_postings = 0
        for entry in journal:
            if not isinstance(entry, dict) or not isinstance(entry.get('postings'), list):
                raise ValueError('History journal requires posting lists')
            actual_postings += len(entry['postings'])
        transactions += max(slots, len(journal))
        postings += max(4 * slots, actual_postings)
        if transactions > 10000 or postings > 40000 or transactions * balance_cells > 1000000:
            raise ValueError('Economy work budget exceeded: maximum 10000 reserved transactions, '
                             '40000 postings, and 1000000 ledger balance-cell updates')

    for record in state['history']:
        if not isinstance(record, dict) or 'policy' not in record:
            raise ValueError('Economy history requires recorded policies')
        reserve(record['policy'], record.get('journal', []))
    for policy in policies:
        reserve(policy)
    return {'reserved_transactions': transactions, 'reserved_postings': postings,
            'ledger_balance_cells': balance_cells, 'ledger_balance_work': transactions * balance_cells,
            'max_transactions': 10000, 'max_postings': 40000, 'max_ledger_balance_work': 1000000}


def _validate(state):
    _object(state, ('banks', 'firms', 'households', 'step', 'history', 'initial_reserves'), 'economy state')
    if set(state) != {'banks', 'firms', 'households', 'step', 'history', 'initial_reserves'}:
        raise ValueError('Incomplete economy state')
    if not isinstance(state['history'], list) or state['step'] != len(state['history']) or not 0 <= state['step'] <= 1000:
        raise ValueError('Invalid bounded step/history')
    for name in ('firms', 'households'):
        if not isinstance(state[name], list) or not 1 <= len(state[name]) <= 100:
            raise ValueError(f'{name} requires 1 to 100 actors')
    if (state['step'] + 1) * (len(state['firms']) + len(state['households'])) > 100000:
        raise ValueError('Economy history budget exceeded')
    ledger = simulate_banking({'banks': state['banks']})
    if _money(state['initial_reserves'], 'initial_reserves') != sum(_money(b['reserves'], 'reserves') for b in ledger['banks']):
        raise ValueError('Aggregate reserves changed from opening anchor')
    banks = {b['id']: b for b in ledger['banks']}
    actors = {}
    for kind in ('households', 'firms'):
        for actor in state[kind]:
            _object(actor, ('id', 'bank') if kind == 'households' else ('id', 'bank', 'worker', 'inventory', 'capacity', 'unit_cost', 'status'), kind)
            aid = actor.get('id')
            if not isinstance(aid, str) or not aid or aid in actors or actor.get('bank') not in banks:
                raise ValueError('Actor requires unique ID and known bank')
            if aid not in banks[actor['bank']]['accounts']:
                raise ValueError('Actor requires an opening bank account')
            actors[aid] = actor
            if kind == 'firms':
                if actor.get('worker') not in {h['id'] for h in state['households']}:
                    raise ValueError('Firm worker must be a household')
                for field in ('inventory', 'capacity'): _count(actor.get(field), field)
                if _money(actor.get('unit_cost'), 'unit_cost') <= 0:
                    raise ValueError('unit_cost must be positive')
                if actor.get('status') not in ('active', 'bankrupt'):
                    raise ValueError('Invalid firm status')
    for bank in banks.values():
        for owner in set(bank['accounts']) | set(bank['loans']):
            if owner not in actors or actors[owner]['bank'] != bank['id']:
                raise ValueError('Every account and loan must belong to its actor at its bank')
        if set(bank['loans']) - {f['id'] for f in state['firms']}:
            raise ValueError('Only firms borrow in this economy')
    _work_budget(state)
    return ledger['banks']


def initialize_economy(config):
    """Create a persistent state from banks, firms and households endowments."""
    _object(config, ('banks', 'firms', 'households'), 'initial economy')
    if set(config) != {'banks', 'firms', 'households'}:
        raise ValueError('Initial economy requires banks, firms and households')
    state = deepcopy(config)
    for firm in state['firms']:
        firm.setdefault('status', 'active')
    state.update(step=0, history=[], initial_reserves=_units(sum(_money(b['reserves'], 'reserves') for b in state['banks'])))
    state['banks'] = _validate(state)
    return state


def step_economy(state, policy, shock=None):
    """Return a new state; errors leave all caller objects unchanged.

    Firm actions: production (units), price (USD/unit), credit_limit (maximum
    outstanding principal), repay (USD), bankrupt (bool). Household actions:
    purchases:{firm:units}. Omitted actions mean zero. Defaults are explicit
    bankruptcy decisions; bank solvency and reserves constrain feasible output.
    Exogenous shock supports inventory_loss only. Missing credit or settlement
    liquidity deterministically rations production/purchases, with audit events.
    """
    banks_list = _validate(state)
    if state['step'] >= 1000:
        raise ValueError('Economy horizon is bounded to 1000 steps')
    _object(policy, ('firms', 'households'), 'policy')
    work = _work_budget(state, [policy])
    shock = {} if shock is None else shock
    _object(shock, ('inventory_loss',), 'shock')
    out = deepcopy(state)
    out['banks'] = banks_list
    actors = {x['id']: x for x in out['firms'] + out['households']}
    firms = {x['id']: x for x in out['firms']}
    households = {x['id']: x for x in out['households']}
    for key, owners in [('firms', firms), ('households', households)]:
        mapping = policy.get(key, {})
        if not isinstance(mapping, dict) or set(mapping) - set(owners):
            raise ValueError('Policy references unknown actor')
    losses = shock.get('inventory_loss', {})
    if not isinstance(losses, dict) or set(losses) - set(firms):
        raise ValueError('Shock references unknown firm')
    actions = {}
    for fid in firms:
        p = policy.get('firms', {}).get(fid, {})
        _object(p, ('production', 'price', 'credit_limit', 'repay', 'bankrupt'), 'firm action')
        if not isinstance(p.get('bankrupt', False), bool): raise ValueError('bankrupt must be boolean')
        actions[fid] = dict(production=_count(p.get('production', 0), 'production'),
                            price=_money(p.get('price', 1), 'price'),
                            credit_limit=_money(p.get('credit_limit', 0), 'credit_limit'),
                            repay=_money(p.get('repay', 0), 'repay'), bankrupt=p.get('bankrupt', False))
        if actions[fid]['price'] <= 0: raise ValueError('price must be positive')
    for hid in households:
        p = policy.get('households', {}).get(hid, {})
        _object(p, ('purchases',), 'household action')
        purchases = p.get('purchases', {})
        if not isinstance(purchases, dict) or set(purchases) - set(firms): raise ValueError('Unknown purchase firm')
        for value in purchases.values(): _count(value, 'purchases')
    events, journal = [], []
    created = repaid = defaulted = 0

    def bank(actor):
        return next(b for b in out['banks'] if b['id'] == actors[actor]['bank'])

    def transact(kind, actor, cents, target=None):
        if not cents: return
        tx = {'kind': kind, 'bank': actors[actor]['bank'], 'amount': _units(cents)}
        if target is None: tx['borrower'] = actor
        else: tx.update(from_account=actor, to_bank=actors[target]['bank'], to_account=target)
        result = simulate_banking({'banks': out['banks'], 'transactions': [tx]})
        out['banks'] = result['banks']
        journal.append({'transaction': tx, 'postings': result['journal'][0]['postings'], 'balanced': True})
        events.extend(result['events'])

    def liquidity(actor, target):
        b = bank(actor)
        return _money(b['reserves'], 'reserves') if actors[actor]['bank'] != actors[target]['bank'] else 100000000000000

    metrics = {}
    opening_goods = sum(f['inventory'] for f in firms.values())
    destroyed = 0
    for fid in sorted(firms):
        firm, p = firms[fid], actions[fid]
        loss = _count(losses.get(fid, 0), 'inventory_loss')
        if loss > firm['inventory']: raise ValueError('Inventory loss exceeds available goods')
        firm['inventory'] -= loss
        destroyed += loss
        m = metrics[fid] = dict(produced=0, sold=0, revenue=0, cost=0, profit=0)
        if p['bankrupt']:
            principal = _money(bank(fid)['loans'].get(fid, 0), 'loan')
            transact('default', fid, principal)
            defaulted += principal
            firm['status'] = 'bankrupt'
            events.append({'kind': 'firm_bankrupt', 'firm': fid, 'written_off': _units(principal)})
        if firm['status'] == 'bankrupt': continue
        b = bank(fid)
        cash, debt = _money(b['accounts'][fid], 'deposit'), _money(b['loans'].get(fid, 0), 'loan')
        credit = max(0, p['credit_limit'] - debt) if _money(b['equity'], 'equity', signed=True) > 0 else 0
        unit_cost = _money(firm['unit_cost'], 'unit_cost')
        produced = min(p['production'], firm['capacity'], (cash + credit) // unit_cost, liquidity(fid, firm['worker']) // unit_cost)
        cost = produced * unit_cost
        loan = max(0, cost - cash)
        transact('originate', fid, loan)
        created += loan
        transact('transfer', fid, cost, firm['worker'])
        firm['inventory'] += produced
        if firm['inventory'] > 1000000: raise ValueError('Inventory exceeds bounded range')
        m.update(produced=produced, cost=cost)
        if produced < p['production']:
            events.append({'kind': 'production_rationed', 'firm': fid, 'requested': p['production'], 'produced': produced, 'fallback': 'reduce_to_funded_settleable_capacity'})
    for hid in sorted(households):
        for fid, requested in sorted(policy.get('households', {}).get(hid, {}).get('purchases', {}).items()):
            price = actions[fid]['price']
            available = firms[fid]['inventory'] if firms[fid]['status'] == 'active' else 0
            bought = min(requested, available, _money(bank(hid)['accounts'][hid], 'deposit') // price, liquidity(hid, fid) // price)
            transact('transfer', hid, bought * price, fid)
            firms[fid]['inventory'] -= bought
            metrics[fid]['sold'] += bought
            metrics[fid]['revenue'] += bought * price
            if bought < requested: events.append({'kind': 'purchase_rationed', 'household': hid, 'firm': fid, 'requested': requested, 'bought': bought})
    for fid in sorted(firms):
        amount = min(actions[fid]['repay'], _money(bank(fid)['accounts'][fid], 'deposit'), _money(bank(fid)['loans'].get(fid, 0), 'loan'))
        transact('repay', fid, amount)
        repaid += amount
    final_goods = sum(f['inventory'] for f in firms.values())
    if opening_goods + sum(m['produced'] - m['sold'] for m in metrics.values()) - destroyed != final_goods:
        raise ValueError('Goods conservation failed')
    def totals(bs, key): return sum(_money(v, key) for b in bs for v in b[key].values())
    if totals(out['banks'], 'accounts') - totals(state['banks'], 'accounts') != created - repaid:
        raise ValueError('Deposit creation/extinction mismatch')
    if totals(out['banks'], 'loans') - totals(state['banks'], 'loans') != created - repaid - defaulted:
        raise ValueError('Debt creation/extinction mismatch')
    for m in metrics.values():
        m['profit'] = m['revenue'] - m['cost']
        for k in ('cost', 'revenue', 'profit'): m[k] = _units(m[k])
    record = {'step': out['step'] + 1, 'policy': deepcopy(policy), 'shock': deepcopy(shock), 'firms': metrics, 'work': work,
              'events': events, 'journal': journal, 'accounting': {'balanced': True, 'reserve_change': 0,
              'loan_created': _units(created), 'loan_repaid': _units(repaid), 'loan_defaulted': _units(defaulted),
              'goods_opening': opening_goods, 'goods_destroyed': destroyed, 'goods_closing': final_goods}}
    out['history'].append(record)
    out['step'] += 1
    _validate(out)
    return out


def simulate_coupled_economy(config):
    """Bounded convenience runner, with policy and exogenous shock sequences."""
    _object(config, ('initial_state', 'policies', 'shocks'), 'coupled simulation')
    policies = config.get('policies')
    if not isinstance(policies, list) or len(policies) > 1000: raise ValueError('policies must contain at most 1000 steps')
    shocks = config.get('shocks', [{} for _ in policies])
    if not isinstance(shocks, list) or len(shocks) != len(policies): raise ValueError('shocks must align with policies')
    state = initialize_economy(config['initial_state'])
    _work_budget(state, policies)
    for policy, shock in zip(policies, shocks): state = step_economy(state, policy, shock)
    return state


def _predict(inputs, parameters, context):
    if context['dt_seconds'] != 86400: raise ValueError('Coupled economy requires daily cadence')
    state = step_economy(inputs['economy_state']['value'], inputs['economy_policy']['value'])
    record = state['history'][-1]
    return {'pressures': [{'port': 'economy_state', 'mode': 'set', 'value': state, 'unit': None, 'strength': 1, 'confidence': 1}],
            'events': record['events'], 'diagnostics': {'accounting': record['accounting'], 'journal': record['journal'],
            'epistemic_status': 'synthetic_scenario', 'calibrated': False}}


def register_coupled_economy_processes(registry):
    port = {'type': 'object', 'unit': None}
    registry.register_process({'id': 'coupled_economy', 'inputs': {'economy_state': port, 'economy_policy': port},
        'outputs': {'economy_state': port}, 'topology': 'Firms employ households; all actors settle at explicit commercial banks.',
        'description': 'Incremental production, consumption and endogenous bank credit under explicit per-step policy.',
        'illustrative': True, 'validated': False})
    registry.register_implementation({'id': 'coupled_economy.deterministic', 'process_id': 'coupled_economy',
        'fidelity': 'deterministic', 'min_step_seconds': 86400, 'max_step_seconds': 86400, 'cost_per_call': 1,
        'output_timing': 'end_of_step', 'description': 'Exact-cent closed settlement with deterministic credit and liquidity rationing.'}, _predict)
    return registry


def schema():
    return {'entity_types': {}, 'relations': {}, 'variables': {
        'economy_state': {'type': 'object', 'unit': None, 'domain': 'entity'},
        'economy_policy': {'type': 'object', 'unit': None, 'domain': 'entity'}}}

sources.worldmodel/economy.py:
"""Bounded, closed-cash daily economy. Behavioral coefficients are assumptions.

USD cash moves between a bank, firms, supplier and explicit customer sector.
This is a cash-funded lender, not a commercial-bank deposit creation model.
Inventory uses weighted-average acquisition cost; loans are floating rate.
"""
from copy import deepcopy
import math


def _number(value, name, minimum=0):
    if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value) or value < minimum:
        raise ValueError(f'{name} must be finite and >= {minimum}')
    return float(value)


def example_economy():
    return {'days': 30, 'energy_price': 10, 'bank': {'cash': 10000, 'annual_rate': .05, 'credit_limit': 10000},
            'supplier': {'cash': 1000}, 'customers': {'cash': 100000},
            'businesses': [{'id': 'factory', 'cash': 1000, 'loan': 0, 'inventory': 20,
                'storage_capacity': 200, 'credit_limit': 2000, 'daily_energy_need': 10,
                'revenue_per_unit': 16, 'policy': {'target_days': 3, 'anticipation': 2,
                                                 'expected_price_change': .25}}],
            'shocks': [{'step': 10, 'energy_price': 14, 'annual_rate': .08}]}


def _prepare(config):
    config = deepcopy(config)
    days = config.get('days', 30)
    if isinstance(days, bool) or not isinstance(days, int) or not 0 <= days <= 10000:
        raise ValueError('days must be an integer in 0..10000')
    price = _number(config['energy_price'], 'energy_price')
    if price == 0:
        raise ValueError('energy_price must be positive')
    bank = {key: _number(config['bank'][key], f'bank.{key}') for key in ('cash', 'annual_rate', 'credit_limit')}
    supplier = {'cash': _number(config['supplier']['cash'], 'supplier.cash')}
    customers = {'cash': _number(config.get('customers', {'cash': 100000})['cash'], 'customers.cash')}
    businesses = config['businesses']
    if not isinstance(businesses, list) or not 1 <= len(businesses) <= 1000 or days * len(businesses) > 100000:
        raise ValueError('businesses and days exceed bounded simulation work budget')
    ids = set()
    for firm in businesses:
        ident = firm['id']
        if not isinstance(ident, str) or not ident or ':' in ident or ident in ids or ident in {'bank', 'supplier', 'customers'}:
            raise ValueError('Business IDs must be distinct nonreserved strings without colons')
        ids.add(ident)
        for key in ('cash', 'loan', 'inventory', 'storage_capacity', 'credit_limit', 'daily_energy_need', 'revenue_per_unit'):
            firm[key] = _number(firm[key], f'{ident}.{key}')
        if firm['loan'] > firm['credit_limit'] or firm['inventory'] > firm['storage_capacity']:
            raise ValueError('Initial credit or storage limit exceeded')
        policy = firm.setdefault('policy', {})
        for key, default in [('target_days', 1), ('anticipation', 0), ('expected_price_change', 0)]:
            policy[key] = _number(policy.get(key, default), f'{ident}.policy.{key}', -1 if key == 'expected_price_change' else 0)
        firm.update(inventory_value=firm['inventory'] * price, defaulted=False, output=0., profit=0., interest=0., energy_spend=0.)
    bank['loans'] = sum(f['loan'] for f in businesses)
    if bank['loans'] > bank['credit_limit']:
        raise ValueError('Initial aggregate bank credit limit exceeded')
    bank.update(equity=bank['cash'] + bank['loans'], interest_income=0., credit_losses=0.)
    shocks = config.get('shocks', [])
    seen = set()
    for shock in shocks:
        step = shock['step']
        if isinstance(step, bool) or not isinstance(step, int) or step < 1 or step in seen:
            raise ValueError('Shock steps must be unique positive integers')
        if set(shock) - {'step', 'energy_price', 'annual_rate'}:
            raise ValueError('Unknown shock field')
        seen.add(step)
        for field in ('energy_price', 'annual_rate'):
            if field in shock:
                _number(shock[field], field)
                if field == 'energy_price' and shock[field] == 0:
                    raise ValueError('energy_price must be positive')
    return days, price, bank, supplier, customers, businesses, {s['step']: s for s in shocks}


def simulate_economy(config):
    """Return daily snapshots, balanced debit/credit journal, events and metrics.

    Each day: apply shocks, pay interest/default, fund and purchase inventories,
    consume energy and sell output. Firm order is explicit credit priority.
    No future shock is observed by purchasing policy: expectations are inputs.
    """
    days, price, bank, supplier, customers, firms, shocks = _prepare(config)
    journal, events, snapshots, ledger = [], [], [], {}

    def post(step, kind, *entries):
        postings = [{'account': account, 'debit': max(amount, 0.), 'credit': max(-amount, 0.)}
                    for account, amount in entries if amount != 0]
        if abs(sum(e['debit'] - e['credit'] for e in postings)) > 1e-7:
            raise ValueError('Unbalanced transaction')
        for e in postings:
            ledger[e['account']] = ledger.get(e['account'], 0.) + e['debit'] - e['credit']
        journal.append({'step': step, 'kind': kind, 'postings': postings})

    post(0, 'opening_bank', ('bank:cash', bank['cash']), ('bank:loans', bank['loans']), ('bank:equity', -bank['equity']))
    for name, actor in [('supplier', supplier), ('customers', customers)]:
        post(0, 'opening_' + name, (name + ':cash', actor['cash']), (name + ':equity', -actor['cash']))
    for f in firms:
        ident = f['id']
        post(0, 'opening_business', (ident + ':cash', f['cash']), (ident + ':inventory', f['inventory_value']),
             (ident + ':loan', -f['loan']), (ident + ':equity', -(f['cash'] + f['inventory_value'] - f['loan'])))

    def snapshot(step):
        bank['equity'] = bank['cash'] + bank['loans']
        for firm in firms:
            firm['equity'] = firm['cash'] + firm['inventory_value'] - firm['loan']
            if firm['equity'] < -1e-9 and not any(e['kind'] == 'insolvency' and e['business'] == firm['id'] for e in events):
                events.append({'step': step, 'kind': 'insolvency', 'business': firm['id'], 'equity': firm['equity'],
                               'recognition': 'Negative book equity; continues operating while daily interest can be paid.'})
        metrics = {'total_cash': bank['cash'] + supplier['cash'] + customers['cash'] + sum(f['cash'] for f in firms),
            'total_loans': bank['loans'], 'total_inventory': sum(f['inventory'] for f in firms),
            'total_output': sum(f['output'] for f in firms), 'total_profit': sum(f['profit'] for f in firms),
            'total_interest': sum(f['interest'] for f in firms), 'total_energy_spend': sum(f['energy_spend'] for f in firms),
            'defaults': sum(f['defaulted'] for f in firms), 'stockouts': sum(e['kind'] == 'stockout' for e in events),
            'bank_equity': bank['equity'], 'business_cash': sum(f['cash'] for f in firms),
            'insolvent_businesses': sum(f['equity'] < -1e-9 for f in firms)}
        snapshots.append(deepcopy({'step': step, 'energy_price': price, 'annual_rate': bank['annual_rate'],
            'metrics': metrics, 'businesses': firms, 'bank': bank, 'supplier': supplier, 'customers': customers}))

    snapshot(0)
    for step in range(1, days + 1):
        if step in shocks:
            shock = shocks[step]
            price = shock.get('energy_price', price)
            bank['annual_rate'] = shock.get('annual_rate', bank['annual_rate'])
            events.append(dict(shock, kind='shock'))
        for firm in firms:
            if firm['defaulted']:
                continue
            ident = firm['id']
            due = firm['loan'] * bank['annual_rate'] / 365
            paid = min(due, firm['cash'])
            if paid:
                firm['cash'] -= paid
                bank['cash'] += paid
                bank['interest_income'] += paid
                firm['interest'] += paid
                firm['profit'] -= paid
                post(step, 'interest', (ident + ':interest_expense', paid), (ident + ':cash', -paid),
                     ('bank:cash', paid), ('bank:interest_revenue', -paid))
            if due - paid > 1e-9:
                loss = firm['loan']
                bank['loans'] -= loss
                bank['credit_losses'] += loss
                firm['loan'] = 0.
                firm['defaulted'] = True
                post(step, 'default', ('bank:credit_loss', loss), ('bank:loans', -loss),
                     (ident + ':loan', loss), (ident + ':debt_relief', -loss))
                events.append({'step': step, 'kind': 'default', 'business': ident, 'principal_written_off': loss,
                               'unpaid_interest': due - paid})
                continue
            policy = firm['policy']
            # Carrying cost uses the declared target horizon; expectations never inspect shocks.
            incentive = max(0., policy['expected_price_change'] - bank['annual_rate'] * policy['target_days'] / 365)
            target = min(firm['storage_capacity'], firm['daily_energy_need'] * policy['target_days'] *
                         (1 + policy['anticipation'] * incentive))
            desired_cost = max(0., target - firm['inventory']) * price
            borrowed = min(max(0., desired_cost - firm['cash']), bank['cash'],
                           max(0., bank['credit_limit'] - bank['loans']), max(0., firm['credit_limit'] - firm['loan']))
            if borrowed:
                bank['cash'] -= borrowed
                bank['loans'] += borrowed
                firm['cash'] += borrowed
                firm['loan'] += borrowed
                post(step, 'loan_origination', ('bank:loans', borrowed), ('bank:cash', -borrowed),
                     (ident + ':cash', borrowed), (ident + ':loan', -borrowed))
            spent = min(desired_cost, firm['cash'])
            purchased = spent / price
            if spent:
                firm['cash'] -= spent
                supplier['cash'] += spent
                firm['inventory'] += purchased
                firm['inventory_value'] += spent
                firm['energy_spend'] += spent
                post(step, 'energy_purchase', (ident + ':inventory', spent), (ident + ':cash', -spent),
                     ('supplier:cash', spent), ('supplier:revenue', -spent))
            if firm['inventory'] + 1e-9 < firm['daily_energy_need']:
                events.append({'step': step, 'kind': 'stockout', 'business': ident,
                               'unmet_energy': firm['daily_energy_need'] - firm['inventory']})
            output = min(firm['daily_energy_need'], firm['inventory'])
            if firm['revenue_per_unit']:
                output = min(output, customers['cash'] / firm['revenue_per_unit'])
            cost = output * (firm['inventory_value'] / firm['inventory'] if firm['inventory'] else 0.)
            revenue = output * firm['revenue_per_unit']
            firm['inventory'] = max(0., firm['inventory'] - output)
            firm['inventory_value'] = max(0., firm['inventory_value'] - cost)
            firm['cash'] += revenue
            customers['cash'] = max(0., customers['cash'] - revenue)
            firm['output'] += output
            firm['profit'] += revenue - cost
            if output:
                post(step, 'production_sale', (ident + ':cost_of_goods', cost), (ident + ':inventory', -cost),
                     (ident + ':cash', revenue), (ident + ':sales_revenue', -revenue),
                     ('customers:consumption_expense', revenue), ('customers:cash', -revenue))
        snapshot(step)
    result = {'snapshots': snapshots, 'journal': journal, 'ledger': ledger, 'events': events,
              'metrics': deepcopy(snapshots[-1]['metrics']), 'status': {'synthetic': True, 'calibrated': False},
              'assumptions': ['USD amounts; energy quantity is a consistent user-chosen unit; one output per energy unit.',
                  'Cash-funded lender; no deposit creation, reserves, interbank market or central bank balance sheet.',
                  'Floating annual loan rate / 365; unpaid daily interest triggers immediate default and full principal writeoff.',
                  'No loan maturity or principal repayment; defaults halt production, with no collateral recovery. Operating profit excludes default debt relief.',
                  'Supplier has unlimited energy at exogenous price; customers have finite cash.',
                  'Business list order is priority for scarce bank cash and customer cash.',
                  'Inventory target = daily need * target days * (1 + anticipation * max(expected price change - annual rate * target days / 365, 0)), capped by storage.',
                  'Behavioral coefficients are illustrative inputs, not calibrated responses; future shocks are not read by firms.']}
    result['accounting'] = validate_accounting(result)
    return result


def validate_accounting(result, tolerance=1e-7):
    """Recompute ledger and verify journals, cash conservation and loan symmetry."""
    ledger = {}
    for entry in result['journal']:
        total = 0.
        for p in entry['postings']:
            debit, credit = _number(p['debit'], 'debit'), _number(p['credit'], 'credit')
            if debit and credit:
                raise ValueError('Posting cannot debit and credit simultaneously')
            total += debit - credit
            ledger[p['account']] = ledger.get(p['account'], 0.) + debit - credit
        if abs(total) > tolerance:
            raise ValueError('Unbalanced journal entry')
    for key in set(ledger) | set(result['ledger']):
        if not math.isclose(ledger.get(key, 0.), result['ledger'].get(key, 0.), abs_tol=tolerance, rel_tol=1e-10):
            raise ValueError('Ledger differs from journal')
    initial = result['snapshots'][0]['metrics']['total_cash']
    for snapshot in result['snapshots']:
        firms, bank = snapshot['businesses'], snapshot['bank']
        if not math.isclose(bank['equity'], bank['cash'] + bank['loans'], abs_tol=tolerance):
            raise ValueError('Bank equity differs from assets')
        cash = bank['cash'] + snapshot['supplier']['cash'] + snapshot['customers']['cash'] + sum(f['cash'] for f in firms)
        if not math.isclose(cash, initial, abs_tol=tolerance, rel_tol=1e-10):
            raise ValueError('Cash conservation violated')
        if not math.isclose(bank['loans'], sum(f['loan'] for f in firms), abs_tol=tolerance):
            raise ValueError('Loan assets and liabilities differ')
        for firm in firms:
            if not math.isclose(firm['equity'], firm['cash'] + firm['inventory_value'] - firm['loan'], abs_tol=tolerance):
                raise ValueError('Business equity differs from net assets')
            if firm['cash'] < -tolerance or firm['loan'] < -tolerance or firm['loan'] > firm['credit_limit'] + tolerance or not -tolerance <= firm['inventory'] <= firm['storage_capacity'] + tolerance:
                raise ValueError('Business balance or capacity constraint violated')
        if bank['cash'] < -tolerance or not -tolerance <= bank['loans'] <= bank['credit_limit'] + tolerance:
            raise ValueError('Bank balance or credit constraint violated')
    last = result['snapshots'][-1]
    expected = {'bank:cash': last['bank']['cash'], 'bank:loans': last['bank']['loans'],
                'supplier:cash': last['supplier']['cash'], 'customers:cash': last['customers']['cash']}
    for firm in last['businesses']:
        expected.update({firm['id'] + ':cash': firm['cash'], firm['id'] + ':loan': -firm['loan'],
                         firm['id'] + ':inventory': firm['inventory_value']})
        ident = firm['id']
        profit = -ledger.get(ident + ':sales_revenue', 0.) - ledger.get(ident + ':cost_of_goods', 0.) - ledger.get(ident + ':interest_expense', 0.)
        if not math.isclose(firm['profit'], profit, abs_tol=tolerance, rel_tol=1e-10):
            raise ValueError('Business operating profit differs from ledger (debt relief excluded)')
    for key, value in expected.items():
        if not math.isclose(ledger.get(key, 0.), value, abs_tol=tolerance, rel_tol=1e-10):
            raise ValueError('Final state differs from journal: ' + key)
    final_firms = last['businesses']
    final_metrics = {'total_cash': sum(value for key, value in expected.items() if key.endswith(':cash')),
        'total_loans': last['bank']['loans'], 'total_inventory': sum(f['inventory'] for f in final_firms),
        'total_output': sum(f['output'] for f in final_firms), 'total_profit': sum(f['profit'] for f in final_firms),
        'total_interest': sum(f['interest'] for f in final_firms), 'total_energy_spend': sum(f['energy_spend'] for f in final_firms),
        'defaults': sum(f['defaulted'] for f in final_firms), 'stockouts': sum(e['kind'] == 'stockout' for e in result['events']),
        'bank_equity': last['bank']['equity'], 'business_cash': sum(f['cash'] for f in final_firms),
        'insolvent_businesses': sum(f['equity'] < -1e-9 for f in final_firms)}
    if set(result['metrics']) != set(final_metrics) or set(last['metrics']) != set(final_metrics):
        raise ValueError('Final metrics fields differ from accounting metrics')
    for key, value in final_metrics.items():
        for metrics in (last['metrics'], result['metrics']):
            if not math.isclose(metrics[key], value, abs_tol=tolerance, rel_tol=1e-10):
                raise ValueError('Final metrics inconsistent with state: ' + key)
    return {'balanced': True, 'cash_conserved': True, 'loan_assets_equal_liabilities': True, 'entries': len(result['journal'])}


def value_bond(face_value, coupon_rate, annual_yield, years, payments_per_year=2):
    """Fixed-coupon clean price at coupon date; nominal compounded yield."""
    face = _number(face_value, 'face_value')
    coupon = _number(coupon_rate, 'coupon_rate')
    years = _number(years, 'years')
    if face == 0 or years == 0 or isinstance(payments_per_year, bool) or not isinstance(payments_per_year, int) or not 1 <= payments_per_year <= 365:
        raise ValueError('Positive face, maturity and integer frequency required')
    y = _number(annual_yield, 'annual_yield', -payments_per_year)
    count = years * payments_per_year
    if y <= -payments_per_year or not count.is_integer() or count > 100000:
        raise ValueError('Maturity must have finite whole coupon periods and valid yield')
    try:
        flows = [(period / payments_per_year,
                  (face * coupon / payments_per_year + (face if period == int(count) else 0)) /
                  (1 + y / payments_per_year) ** period) for period in range(1, int(count) + 1)]
        price = sum(pv for _, pv in flows)
        duration = sum(time * pv for time, pv in flows) / price
        if not math.isfinite(price) or not math.isfinite(duration):
            raise ValueError('Bond calculation overflow')
    except (OverflowError, ZeroDivisionError) as exc:
        raise ValueError('Bond calculation outside finite numeric range') from exc
    return {'price': price, 'macaulay_duration_years': duration,
            'modified_duration': duration / (1 + y / payments_per_year),
            'dv01': price * duration / (1 + y / payments_per_year) * .0001}

sources.worldmodel/environments.py:
"""Environments are input/output adapters over materializations, independent of actor types.

Evaluator protocol: evaluate(history, seed) -> {snapshots, execution?, artifact?}.
History contains routed input values. Evaluators must replay deterministically or
own equivalent transactional state; the built-in adapter uses bounded replay.
"""
from copy import deepcopy
from contextlib import nullcontext
from datetime import timedelta
import math
from .util import canonical


class BudgetExceeded(ValueError):
    """An evaluator cannot execute another prefix within its declared work budget."""


def _finite(value):
    if type(value) not in (int,float) or not math.isfinite(value):raise ValueError('Expected finite numeric value')
    return value


def select_output(result,selector):
    if not {'entity','variable','unit'}<=set(selector):raise ValueError('Output selectors require entity, variable and explicit unit')
    rows=[r for r in result['snapshots'] if r['entity']==selector['entity'] and r['variable']==selector['variable']]
    if not rows:raise ValueError('Missing selected output: '+str(selector))
    # Materializers emit snapshots in chronological order; adapters must preserve this contract.
    last=rows[-1];ties=[r for r in rows if r['time']==last['time']]
    if len({canonical([r['value'],r.get('unit')]) for r in ties})!=1:raise ValueError('Conflicting selected outputs')
    if last.get('unit')!=selector['unit']:raise ValueError('Selected output unit mismatch')
    value=last['value']
    path=selector.get('path',[])
    if not isinstance(path,list) or len(path)>20:raise ValueError('Output path must be a bounded list')
    for part in path:
        if isinstance(value,dict) and isinstance(part,str) and part in value:value=value[part]
        elif isinstance(value,list) and type(part) is int and 0<=part<len(value):value=value[part]
        else:raise ValueError('Missing selected output path')
    if value is None:raise ValueError('Selected output is unknown')
    return deepcopy(value)


class Environment:
    def __init__(self,evaluate,spec):
        self.evaluate=evaluate;self.spec=deepcopy(spec);canonical(spec)
        for field in ('actions','observations','reward','max_steps'):
            if field not in spec:raise ValueError('Missing environment specification: '+field)
        if not isinstance(spec['actions'],dict) or not isinstance(spec['observations'],dict) or not spec['observations']:
            raise ValueError('Named actions and nonempty observations required')
        if len(spec['actions'])>100 or len(spec['observations'])>100:raise ValueError('Environment port budget exceeded')
        if type(spec['max_steps']) is not int or not 1<=spec['max_steps']<=1000:raise ValueError('max_steps must be in 1..1000')
        self.spec.setdefault('max_evaluations',spec['max_steps']+1)
        if type(self.spec['max_evaluations']) is not int or not 1<=self.spec['max_evaluations']<=1001:raise ValueError('Invalid evaluation budget')
        destinations=set()
        for descriptor in spec['actions'].values():
            if not {'binding','port','type','unit'}<=set(descriptor):raise ValueError('Action requires binding, port, type and unit')
            key=(descriptor['binding'],descriptor['port'])
            if key in destinations:raise ValueError('Duplicate action input destination')
            destinations.add(key)
            if descriptor['type']=='number':
                if _finite(descriptor['minimum'])>_finite(descriptor['maximum']):raise ValueError('Invalid action bounds')
            elif descriptor['type'] not in ('string','boolean','object','array','vector'):raise ValueError('Unsupported action type')
        terms=spec['reward'].get('terms')
        if not isinstance(terms,list) or len(terms)>100:raise ValueError('Explicit bounded reward terms required')
        for term in terms:
            if term['mode'] not in ('value','delta'):raise ValueError('Unsupported reward mode')
            if _finite(term['scale'])<=0:raise ValueError('Reward normalization scale must be positive')
            _finite(term['weight'])
        self._history=[];self._result=None;self._done=False;self._evaluations=0;self._seed=0

    @property
    def history(self):return deepcopy(self._history)

    @property
    def materialization(self):
        """Privileged inspection; never implicitly included in agent observations/info."""
        return deepcopy(self._result)

    def _outputs(self,result):
        return {name:select_output(result,selector) for name,selector in self.spec['observations'].items()}

    def _terminated(self,result):
        rule=self.spec.get('termination')
        if not rule:return False
        value=_finite(select_output(result,rule['selector']));threshold=_finite(rule['value'])
        if rule['operator']=='gte':return value>=threshold
        if rule['operator']=='lte':return value<=threshold
        raise ValueError('Unsupported termination operator')

    def _reward(self,before,after):
        reward=0.0
        for term in self.spec['reward']['terms']:
            value=_finite(select_output(after,term['selector']))
            if term['mode']=='delta':value-=_finite(select_output(before,term['selector']))
            reward+=term['weight']*value/term['scale']
        return _finite(reward)

    def _call(self,history,seed):
        if self._evaluations>=self.spec['max_evaluations']:raise BudgetExceeded('Evaluation budget exhausted')
        self._evaluations+=1 # Failed evaluations also consume work budget.
        result=self.evaluate(deepcopy(history),seed)
        if len(canonical(result))>32*1024*1024:raise ValueError('Materialization output exceeds 32 MiB environment limit')
        return result

    def reset(self,seed=0):
        if type(seed) is not int:raise ValueError('Seed must be integer')
        self._evaluations=0
        with self.evaluate.transaction() if hasattr(self.evaluate,'transaction') else nullcontext():
            result=self._call([],seed);observation=self._outputs(result)
            self._reward(result,result) # Validate reward selectors even before a transition.
            done=self._terminated(result)
        self._history=[];self._seed=seed;self._result=deepcopy(result);self._done=done or self._evaluations>=self.spec['max_evaluations']
        return observation,{'step':0,'terminated':done,'truncated':self._evaluations>=self.spec['max_evaluations'],'reward_unit':'normalized_score'}

    def step(self,actions):
        if self._result is None or self._done:raise ValueError('Reset required before stepping or after episode end')
        if not isinstance(actions,dict) or set(actions)!=set(self.spec['actions']):raise ValueError('Action names must exactly match declared inputs')
        if len(canonical(actions))>65536:raise ValueError('Action payload exceeds 64 KiB')
        inputs=[]
        for name,descriptor in self.spec['actions'].items():
            value=deepcopy(actions[name]);kind=descriptor['type']
            checks={'number':lambda x:type(x) in (int,float),'string':lambda x:isinstance(x,str),
                    'boolean':lambda x:type(x) is bool,'object':lambda x:isinstance(x,dict),
                    'array':lambda x:isinstance(x,list),'vector':lambda x:isinstance(x,list) and all(type(v) in (int,float) for v in x)}
            if not checks[kind](value):raise ValueError('Action type mismatch: '+name)
            if kind=='number' and not descriptor['minimum']<=_finite(value)<=descriptor['maximum']:raise ValueError('Action outside declared bounds')
            if 'choices' in descriptor and value not in descriptor['choices']:raise ValueError('Action outside declared choices')
            inputs.append({'binding':descriptor['binding'],'port':descriptor['port'],'value':value,'unit':descriptor['unit']})
        history=self._history+[{'inputs':inputs}]
        try:
            with self.evaluate.transaction() if hasattr(self.evaluate,'transaction') else nullcontext():
                result=self._call(history,self._seed)
                observation=self._outputs(result);reward=self._reward(self._result,result)
                terminated=self._terminated(result)
        except BudgetExceeded as error:
            self._done=True
            return self._outputs(self._result),0.0,False,True,{'step':len(self._history),'reward_unit':'normalized_score','truncation_reason':str(error)}
        truncated=len(history)>=self.spec['max_steps'] or self._evaluations>=self.spec['max_evaluations']
        self._history=history;self._result=deepcopy(result);self._done=terminated or truncated
        return observation,reward,terminated,truncated,{'step':len(history),'reward_unit':'normalized_score'}


class TemporalEvaluator:
    """Adapt any current temporal view with declared literal input ports by full-prefix replay.

Observed views support read-only trajectories (empty actions). To control a forecast,
expose process literal input ports. Group outputs work unchanged. External agent
backends are unsupported because replay would repeat their side effects/costs.
"""
    def __init__(self,store,graph_ref,request,step_seconds,registry=None,max_total_calls=10000):
        from .materialize import seconds
        from .model import instant
        self.store=store;self.graph_ref=deepcopy(graph_ref);self.request=deepcopy(request)
        self.step_seconds=seconds(step_seconds,'environment step_seconds');self.start=instant(request['start'])
        self.end=instant(request['end']);self.registry=registry
        if type(max_total_calls) is not int or not 1<=max_total_calls<=100000:raise ValueError('Invalid replay call budget')
        if request.get('interventions'):raise ValueError('Environment history owns intervention schedule')
        self.max_total_calls=max_total_calls;self.total_calls=0
        # Pin implementation/cadence once; cost-based selection must not change with prefix length.
        from .materialize import _request, _plan
        from .process_library import default_registry
        self.registry=deepcopy(registry) if registry is not None else default_registry()
        template={**self.request,'step_seconds':self.step_seconds}
        parsed,start,finish,_,targets=_request(template)
        bindings,_,_,_=_plan(self.registry,parsed,targets,(finish-start).total_seconds(),None)
        pinned={b['id']:b for b in bindings}
        for binding in self.request.get('bindings',[]):
            if binding['id'] in pinned:
                selected=pinned[binding['id']]
                if round(self.step_seconds*1000000)%round(selected['cadence_seconds']*1000000):
                    raise ValueError('Environment step must align with every active process cadence')
                binding['implementation_id']=selected['implementation']['id']
                binding['cadence_seconds']=selected['cadence_seconds']

    def __call__(self,history,seed):
        from .materialize import materialize, _request, _plan
        from .process_library import default_registry
        if not history:self.total_calls=0
        end=self.start+timedelta(seconds=len(history)*self.step_seconds)
        if end>self.end:raise ValueError('Environment exceeds materialization horizon')
        request=deepcopy(self.request)
        request.update(end=end.isoformat(),step_seconds=self.step_seconds,seed=seed)
        request['interventions']=[{'time':(self.start+timedelta(seconds=i*self.step_seconds)).isoformat(),**port}
                                  for i,item in enumerate(history) for port in item['inputs']]
        registry=self.registry or default_registry()
        parsed,start,finish,_,targets=_request(request)
        bindings,_,plan,_=_plan(registry,parsed,targets,(finish-start).total_seconds(),None)
        if any(b['implementation']['fidelity']=='agent' for b in bindings):raise ValueError('Replay adapter cannot execute live agent backends')
        # _plan preflights process calls; reserve before invoking the materializer.
        calls=sum((round((finish-start).total_seconds()*1000000)+round(b['cadence_seconds']*1000000)-1)//round(b['cadence_seconds']*1000000) for b in bindings)
        if self.total_calls+calls>self.max_total_calls:raise BudgetExceeded('Cumulative environment replay call budget exceeded')
        self.total_calls+=calls
        return materialize(self.store,self.graph_ref,request,registry=registry)


# Stateful alternative; TemporalEvaluator remains the replay reference.
from .checkpoints import CheckpointEvaluator

